async resizeImageIfNeeded(file) {
  // Only raster images can be downscaled; keep SVG/GIF and non-images untouched
  if (!file?.type?.startsWith('image/')) return file
  if (['image/svg+xml', 'image/gif'].includes(file.type)) return file
  try {
    const bitmap = await createImageBitmap(file)
    const { width, height } = bitmap
    const scale = Math.min(1, this.MAX_IMAGE_DIMENSION / Math.max(width, height))
    // Already within bounds – keep the original bytes to avoid quality loss
    if (scale === 1) {
      bitmap.close?.()
      return file
    }
    const targetWidth = Math.max(1, Math.round(width * scale))
    const targetHeight = Math.max(1, Math.round(height * scale))
    const canvas = document.createElement('canvas')
    canvas.width = targetWidth
    canvas.height = targetHeight
    const ctx = canvas.getContext('2d')
    ctx.drawImage(bitmap, 0, 0, targetWidth, targetHeight)
    bitmap.close?.()
    const blob = await new Promise(resolve =>
      canvas.toBlob(resolve, 'image/jpeg', this.IMAGE_QUALITY)
    )
    if (!blob) return file
    const name = file.name.replace(/\.[^.]+$/, '') + '.jpg'
    return new File([blob], name, { type: 'image/jpeg', lastModified: Date.now() })
  } catch (error) {
    console.error('[IMAGE] Resize failed, using original file', error)
    return file
  }
},

async prepareAttachmentFromFile(file) {
  if (!this.validateImageSize(file)) return null
  try {
    const optimized = await this.resizeImageIfNeeded(file)
    const attachment = await ChatAttachment.fromFile(optimized)
    return attachment
  } catch (error) {
    console.error("Error preparing attachment:", error)
    this.$ui?.addNotification?.({ text: "Failed to process file", type: 'error' })
    return null
  }
},

async prepareAttachmentFromUrl(imgUrl) {
  try {
    const response = await fetch(imgUrl)
    if (!response.ok) {
      console.error(`Failed to fetch image from URL: ${imgUrl}`)
      return null
    }
    const blob = await response.blob()
    const file = new File([blob], this.extractFileNameFromUrl(imgUrl), { type: blob.type })
    const optimized = await this.resizeImageIfNeeded(file)
    return await ChatAttachment.fromFile(optimized)
  } catch (error) {
    console.error("Error preparing attachment from URL:", error)
    this.$ui?.addNotification?.({ text: "Failed to process image URL", type: 'error' })
    return null
  }
},

