// ─── Image Editor Methods ───────────────────────────────
async openImageEditor(file, attachmentIndex = null) {
  this.pendingPasteImage = file
  this.editingAttachmentIndex = attachmentIndex
  this.imageOptimizationPreviewUrl = URL.createObjectURL(file)
  this.imageEditorRotation = 0
  this.imageEditorFlipH = false
  this.imageEditorFlipV = false
  this.showCropOverlay = false
  this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  this.showImageOptimizationModal = true
},

closeImageOptimizationModal() {
  if (this.imageOptimizationPreviewUrl) {
    URL.revokeObjectURL(this.imageOptimizationPreviewUrl)
  }
  this.imageOptimizationPreviewUrl = null
  this.pendingPasteImage = null
  this.editingAttachmentIndex = null
  this.imageEditorRotation = 0
  this.imageEditorFlipH = false
  this.imageEditorFlipV = false
  this.showCropOverlay = false
  this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  this.imageOptimizationProcessing = false
  this.showImageOptimizationModal = false
},

onImageEditorLoad(event) {
  const img = event.target
  this.imageEditorNaturalSize = {
    width: img.naturalWidth,
    height: img.naturalHeight
  }
  this.imageEditorDisplaySize = {
    width: img.clientWidth,
    height: img.clientHeight
  }
},

get imagePreviewStyle() {
  const transforms = []
  if (this.imageEditorFlipH) transforms.push('scaleX(-1)')
  if (this.imageEditorFlipV) transforms.push('scaleY(-1)')
  if (this.imageEditorRotation) transforms.push(`rotate(${this.imageEditorRotation}deg)`)
  return {
    transform: transforms.join(' '),
    transition: 'transform 200ms ease'
  }
},

rotateImage(degrees) {
  this.imageEditorRotation = (this.imageEditorRotation + degrees + 360) % 360
  // Adjust crop rectangle for rotation? For simplicity, reset crop
  this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  this.showCropOverlay = false
},

flipImage(direction) {
  if (direction === 'horizontal') this.imageEditorFlipH = !this.imageEditorFlipH
  else this.imageEditorFlipV = !this.imageEditorFlipV
  // Reset crop
  this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  this.showCropOverlay = false
},

resetImageTransformations() {
  this.imageEditorRotation = 0
  this.imageEditorFlipH = false
  this.imageEditorFlipV = false
  this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  this.showCropOverlay = false
},

toggleCropMode() {
  this.showCropOverlay = !this.showCropOverlay
  if (!this.showCropOverlay) {
    this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
  }
},

startCrop(event) {
  if (!this.showCropOverlay) return
  this.cropDragActive = true
  const rect = event.currentTarget.getBoundingClientRect()
  this.cropDragStart = {
    x: (event.clientX - rect.left) / rect.width,
    y: (event.clientY - rect.top) / rect.height
  }
  this.cropDragCurrent = { ...this.cropDragStart }
},

updateCrop(event) {
  if (!this.cropDragActive) return
  const rect = event.currentTarget.getBoundingClientRect()
  this.cropDragCurrent = {
    x: (event.clientX - rect.left) / rect.width,
    y: (event.clientY - rect.top) / rect.height
  }
  this.cropRect = {
    x: Math.min(this.cropDragStart.x, this.cropDragCurrent.x),
    y: Math.min(this.cropDragStart.y, this.cropDragCurrent.y),
    width: Math.abs(this.cropDragCurrent.x - this.cropDragStart.x),
    height: Math.abs(this.cropDragCurrent.y - this.cropDragStart.y)
  }
  // Clamp to [0,1]
  this.cropRect.x = Math.max(0, Math.min(this.cropRect.x, 1))
  this.cropRect.y = Math.max(0, Math.min(this.cropRect.y, 1))
  if (this.cropRect.x + this.cropRect.width > 1) this.cropRect.width = 1 - this.cropRect.x
  if (this.cropRect.y + this.cropRect.height > 1) this.cropRect.height = 1 - this.cropRect.y
},

endCrop() {
  this.cropDragActive = false
},

get cropOverlayStyle() {
  return {
    left: `${this.cropRect.x * 100}%`,
    top: `${this.cropRect.y * 100}%`,
    width: `${this.cropRect.width * 100}%`,
    height: `${this.cropRect.height * 100}%`
  }
},

async processEditedImage(file) {
  // Load image into a canvas
  const bitmap = await createImageBitmap(file)
  let { width, height } = bitmap

  // Apply rotation (swap dimensions for 90/270)
  if (this.imageEditorRotation === 90 || this.imageEditorRotation === 270) {
    ;[width, height] = [height, width]
  }

  // Set canvas size (crop area after rotation)
  const cropX = Math.round(this.cropRect.x * width)
  const cropY = Math.round(this.cropRect.y * height)
  const cropW = Math.max(1, Math.round(this.cropRect.width * width))
  const cropH = Math.max(1, Math.round(this.cropRect.height * height))

  const canvas = document.createElement('canvas')
  canvas.width = cropW
  canvas.height = cropH
  const ctx = canvas.getContext('2d')

  // Apply transformations
  ctx.translate(cropW / 2, cropH / 2)
  if (this.imageEditorRotation) ctx.rotate(this.imageEditorRotation * Math.PI / 180)
  if (this.imageEditorFlipH) ctx.scale(-1, 1)
  if (this.imageEditorFlipV) ctx.scale(1, -1)
  ctx.drawImage(bitmap, -cropX - cropW/2, -cropY - cropH/2, width, height)

  bitmap.close?.()

  // Downscale if needed
  const maxDim = this.imageOptimizationSettings.maxDimension
  const img = new Image()
  img.src = canvas.toDataURL('image/png')
  await new Promise(resolve => { img.onload = resolve })
  const scale = Math.min(1, maxDim / Math.max(img.width, img.height))
  if (scale < 1) {
    const w = Math.max(1, Math.round(img.width * scale))
    const h = Math.max(1, Math.round(img.height * scale))
    const scaledCanvas = document.createElement('canvas')
    scaledCanvas.width = w
    scaledCanvas.height = h
    const scaledCtx = scaledCanvas.getContext('2d')
    scaledCtx.drawImage(img, 0, 0, w, h)
    canvas = scaledCanvas
  }

  // Encode to JPEG
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', this.imageOptimizationSettings.quality))
  if (!blob) return file

  const name = file.name.replace(/\.[^.]+$/, '') + (this.imageEditorRotation || this.imageEditorFlipH || this.imageEditorFlipV || this.showCropOverlay ? '_edited' : '') + '.jpg'
  return new File([blob], name, { type: 'image/jpeg', lastModified: Date.now() })
},

async confirmImageOptimization() {
  if (!this.pendingPasteImage || this.imageOptimizationProcessing) return
  this.imageOptimizationProcessing = true
  try {
    const processedFile = await this.processEditedImage(this.pendingPasteImage)
    const attachment = await ChatAttachment.fromFile(processedFile)

    if (this.editingAttachmentIndex !== null) {
      // Replace existing attachment
      this.$set(this.attachments, this.editingAttachmentIndex, attachment)
    } else {
      // New attachment from paste
      this.attachments.push(attachment)
    }
  } catch (error) {
    console.error('Error processing image:', error)
    this.$ui?.addNotification?.({ text: 'Failed to process image', type: 'error' })
  } finally {
    this.closeImageOptimizationModal()
  }
},

async editAttachment(index) {
  const attachment = this.attachments[index]
  if (!attachment) return
  // Convert attachment to File for editing
  let file
  try {
    file = await attachment.toFile?.() || new File([await (await fetch(attachment.url)).blob()], attachment.name, { type: attachment.type })
  } catch (e) {
    console.error('Failed to get file from attachment', e)
    return
  }
  this.openImageEditor(file, index)
},

formatFileSize(bytes) {
  if (!bytes) return '0 KB'
  const units = ['B', 'KB', 'MB', 'GB']
  const i = Math.floor(Math.log(bytes) / Math.log(1024))
  return `${(bytes / Math.pow(1024, i)).toFixed(2)} ${units[i]}`
},

async onContentPaste(e) {
  if (!e.clipboardData?.items) return
  const stop = () => { e.preventDefault(); e.stopPropagation(); return false }
  const imageFile = await this.chatSvc.parseImageFromPaste(e)
  if (imageFile) {
    this.openImageEditor(imageFile)  // Open editor for pasted image
    return stop()
  }
  // ... rest unchanged
},

