              <span v-if="imageSaving" class="loading loading-xs"></span>
              Apply Changes
            </button>
          </div>
        </div>
      </template>

      <!-- ... (rest of the template unchanged) ... -->
    </div>
  </modal>
</template>

<script>
import ChatAttachment from '@/api/model/ChatAttachment.js'

export default {
  name: 'ChatAttachmentPreview',
  props: {
    attachments: {
      type: Array,
      default: () => [],
      validator(value) {
        return Array.isArray(value)
      }
    },
    showSelector: {
      type: Boolean,
      default: false
    }
  },
  emits: ['remove-attachment', 'update-attachment'],
  data() {
    return {
      fileObjects: [],
      showModal: false,
      selectedIndex: null,
      hoverPreview: null,
      editSourceImage: null,
      editRotation: 0,
      editZoom: 1,
      editResizeWidth: 0,
      editResizeHeight: 0,
      editKeepAspect: true,
      cropEnabled: false,
      cropRect: { x: 0, y: 0, width: 1, height: 1 },
      cropDragActive: false,
      cropDragStart: { x: 0, y: 0 },
      cropDragCurrent: { x: 0, y: 0 },
      imageSaving: false,
      editControlsVisible: false,
      editScale: 100,
      updatingFromSlider: false  // Flag to prevent watcher loops
    }
  },
  computed: {
    currentAttachment() {
      return this.selectedIndex !== null ? this.fileObjects[this.selectedIndex] : null
    },
    cropOverlayStyle() {
      return {
        left: `${this.cropRect.x * 100}%`,
        top: `${this.cropRect.y * 100}%`,
        width: `${this.cropRect.width * 100}%`,
        height: `${this.cropRect.height * 100}%`
      }
    },
    finalImageSize() {
      if (!this.editSourceImage) return null
      const { width: fullW, height: fullH } = this.getRotatedSourceDimensions()
      const cropW = Math.max(1, Math.round(this.cropRect.width * fullW))
      const cropH = Math.max(1, Math.round(this.cropRect.height * fullH))
      const targetW = Math.max(1, Math.round(this.editResizeWidth || cropW))
      const targetH = Math.max(1, Math.round(this.editResizeHeight || cropH))
      return { width: targetW, height: targetH }
    },
    // Estimate final file size in KB based on area ratio and format adjustment
    estimatedFileSizeKB() {
      if (!this.editSourceImage || !this.currentAttachment || !this.finalImageSize) return 0
      const originalW = this.editSourceImage.naturalWidth
      const originalH = this.editSourceImage.naturalHeight
      const originalArea = originalW * originalH
      const finalArea = this.finalImageSize.width * this.finalImageSize.height
      const originalSizeBytes = this.currentAttachment.file_size

      // Basic area scaling
      let estimatedSize = originalSizeBytes * (finalArea / originalArea)

      // Adjust for potential format conversion (jpg compression usually 10-30% smaller)
      if (this.currentAttachment.file_type !== 'image/png') {
        estimatedSize *= 0.85  // Heuristic for JPEG
      }

      return Math.max(1, Math.round(estimatedSize / 1024))
    }
  },
  watch: {
    attachments: {
      immediate: true,
      handler(newVal) {
        this.fileObjects = newVal.map(attachment => {
          if (attachment instanceof ChatAttachment) {
            return attachment
          }
          return ChatAttachment.fromJSON(attachment)
        })
      }
    },
    // When user manually edits the number inputs, update the scale slider accordingly
    editResizeWidth(newVal) {
      this.updateScaleFromDimensions('width', newVal)
    },
    editResizeHeight(newVal) {
      this.updateScaleFromDimensions('height', newVal)
    }
  },
  beforeUnmount() {
    this.endCrop()
  },
  methods: {
    // ... (existing methods unchanged) ...

    // Update the scale percentage based on current crop dimensions and a given width/height
    updateScaleFromDimensions(changedDimension, value) {
      if (this.updatingFromSlider) return
      if (!this.editSourceImage) return
      const { width: fullW, height: fullH } = this.getRotatedSourceDimensions()
      const cropW = Math.max(1, Math.round(this.cropRect.width * fullW))
      const cropH = Math.max(1, Math.round(this.cropRect.height * fullH))

      // Determine the base dimension that corresponds to 100%
      const baseDimension = changedDimension === 'width' ? cropW : cropH
      const otherDimension = changedDimension === 'width' ? this.editResizeHeight : this.editResizeWidth
      const otherBaseDimension = changedDimension === 'width' ? cropH : cropW

      if (value <= 0 || !baseDimension) {
        this.editScale = 100
        return
      }

      // Calculate scale as percentage of the base dimension
      let scale = Math.round((value / baseDimension) * 100)

      // If aspect ratio is locked and the other dimension was also changed proportionally,
      // ensure the scale is consistent (optional; we trust the user's input)
      if (this.editKeepAspect && otherDimension > 0) {
        const otherScale = Math.round((otherDimension / otherBaseDimension) * 100)
        if (Math.abs(scale - otherScale) > 1) {
          // The user likely changed only one dimension; reset scale to 100 to avoid misleading percentage
          scale = 100
          return
        }
      }

      this.editScale = Math.max(10, Math.min(100, scale))
    },

    // Handle slider input: set width/height based on crop dimensions and scale
    onScaleSliderChange(event) {
      const scale = Number(event.target.value)
      if (!scale || !this.editSourceImage) return

      this.updatingFromSlider = true
      this.editScale = scale

      const { width: fullW, height: fullH } = this.getRotatedSourceDimensions()
      const cropW = Math.max(1, Math.round(this.cropRect.width * fullW))
      const cropH = Math.max(1, Math.round(this.cropRect.height * fullH))

      this.editResizeWidth = Math.max(1, Math.round(cropW * scale / 100))
      this.editResizeHeight = Math.max(1, Math.round(cropH * scale / 100))

      // Reset flag after a tick to allow future user edits
      this.$nextTick(() => {
        this.updatingFromSlider = false
      })
    },

    // Ensure editScale is set correctly when the editor initializes or resets
    initImageEditor() {
      const attachment = this.currentAttachment
      if (!attachment?.isImage?.()) {
        this.editSourceImage = null
        return
      }
      const img = new Image()
      img.onload = () => {
        this.editSourceImage = img
        this.editRotation = 0
        this.editZoom = 1
        this.editKeepAspect = true
        this.cropEnabled = false
        this.cropRect = { x: 0, y: 0, width: 1, height: 1 }
        this.editScale = 100
        this.syncResizeDimensions()
        this.$nextTick(() => this.drawPreview())
      }
      img.src = `data:${attachment.file_type};base64,${attachment.base64_data}`
    },

    // ... (other methods unchanged) ...
  }
}
</script>
```

**Explanation of changes:**
1. **Scale slider**: 
   - Added `editScale` data (default 100) and `updatingFromSlider` flag.
   - Added `<input type="range">` in the template, bound to `editScale`, with `@input="onScaleSliderChange"`.
   - `onScaleSliderChange` calculates new width/height from the current crop area (or full image if no crop) multiplied by the scale percentage.
   - When the user manually changes the width/height number inputs, watchers call `updateScaleFromDimensions` to update the slider position if the dimensions correspond to a valid scale.

2. **Estimated final size in KB**:
   - Added computed `estimatedFileSizeKB` that scales the original file size by the ratio of the final pixel area to the original area, with a slight adjustment if the image is converted to JPEG.
   - Displayed next to the output dimensions in the UI: `(~{{ estimatedFileSizeKB }} KB)`.

3. **Initialization & reset**:
   - Set `editScale = 100` in `initImageEditor` and `resetImageEditor` to keep slider in sync.

The changes preserve the existing functionality while adding the requested sliders and file size display. The sliders provide an intuitive way to reduce image size, and the estimated KB keeps the user informed before applying.

